# Analyze connectivity of DEMO output 6s
output_sixes = [(6, 6), (6, 7), (6, 8), (6, 10), (8, 6), (8, 8), (8, 10), (9, 7)]

# Build graph of adjacencies
from collections import defaultdict
adjacency = defaultdict(list)

for r, c in output_sixes:
    # Check horizontal neighbors
    for dc in [-1, 1]:
        nr, nc = r, c + dc
        if (nr, nc) in output_sixes:
            adjacency[(r, c)].append((nr, nc))
            adjacency[(nr, nc)].append((r, c))
    # Check vertical neighbors
    for dr in [-1, 1]:
        nr, nc = r + dr, c
        if (nr, nc) in output_sixes:
            adjacency[(r, c)].append((nr, nc))
            adjacency[(nr, nc)].append((r, c))

print("Adjacency list:")
for pos in sorted(output_sixes):
    print(f"  {pos}: {sorted(adjacency[pos])}")

# Find connected components
visited = set()
components = []

for start in output_sixes:
    if start not in visited:
        component = []
        stack = [start]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                component.append(node)
                for neighbor in adjacency[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)
        components.append(sorted(component))

print(f"\nConnected components: {len(components)}")
for i, comp in enumerate(components):
    print(f"  Component {i}: {comp}")

# All kept 6s belong to same component?
if len(components) == 1:
    print("\n✓ All kept 6s are connected!")
else:
    print(f"\n✗ {len(components)} separate components found")

